1	import { copyFile, mkdir, mkdtemp, rm, writeFile } from 'node:fs/promises';
2	import { tmpdir } from 'node:os';
3	import { join, resolve } from 'node:path';
4	import { fileURLToPath } from 'node:url';
5	import { bundle } from '@remotion/bundler';
6	import { ensureBrowser, openBrowser, renderMedia, renderStill, selectComposition } from '@remotion/renderer';
7	import type { LineTiming, RenderArtifact, Scene, Storyboard } from '@dailies/core';
8	import { COMPOSITION_ID, NARRATION_FILE, type ReelProps } from './remotion/config';
9	import { toSrt } from './srt';
10	import { buildTimeline } from './timeline';
11	
12	const ENTRY_POINT = fileURLToPath(new URL('./remotion/index.ts', import.meta.url));
13	// The bundler resolves modules from its root, which defaults to the process's working directory. The worker and the
14	// command-line tool start elsewhere, so the root is pinned to this package.
15	const PACKAGE_ROOT = fileURLToPath(new URL('..', import.meta.url));
16	const TIMEOUT_MS = 120_000;
17	
18	type Browser = Awaited<ReturnType<typeof openBrowser>>;
19	type Composition = Awaited<ReturnType<typeof selectComposition>>;
20	interface Stage { serveUrl: string; composition: Composition; browser: Browser }
21	
22	const middle = (slot: { startFrame: number; durationInFrames: number }) => slot.startFrame + Math.floor(slot.durationInFrames / 2);
23	
24	const SCENE_TYPES = new Set<string>(['title', 'prompt', 'terminal', 'diff', 'stats', 'flag', 'end'] satisfies Scene['type'][]);
25	
26	/**
27	 * File name of the still for scene `index`. Stills are numbered because scene ids come from a model and need not
28	 * be unique; the type is only used when it is one of ours, so nothing read from a storyboard can steer the path.
29	 */
30	export function stillName(index: number, type: string): string {
31	  return `${String(index + 1).padStart(2, '0')}-${SCENE_TYPES.has(type) ? type : 'scene'}.png`;
32	}
33	
34	/** Bundles the composition with `publicDir`, opens one browser for every render in `fn`, and cleans both up. */
35	async function withComposition<T>(inputProps: ReelProps, publicDir: string | null, fn: (stage: Stage) => Promise<T>): Promise<T> {
36	  const work = await mkdtemp(join(tmpdir(), 'dailies-reel-'));
37	  let browser: Browser | undefined;
38	  try {
39	    const emptyPublic = join(work, 'public');
40	    await mkdir(emptyPublic);
41	    const serveUrl = await bundle({ entryPoint: ENTRY_POINT, publicDir: publicDir ?? emptyPublic, outDir: join(work, 'bundle') });
42	    // A browser binary can be named explicitly. On macOS a binary that lives under a privacy-protected folder
43	    // (Desktop, Documents) stops producing frames once the screen locks, and every render then times out waiting
44	    // for the root component; pointing this at a copy outside those folders avoids it.
45	    const browserExecutable = process.env.DAILIES_BROWSER_EXECUTABLE || null;
46	    if (!browserExecutable) await ensureBrowser();
47	    browser = await openBrowser('chrome', { browserExecutable });
48	    const composition = await selectComposition({ serveUrl, id: COMPOSITION_ID, inputProps, puppeteerInstance: browser, timeoutInMilliseconds: TIMEOUT_MS });
49	    return await fn({ serveUrl, composition, browser });
50	  } finally {
51	    await browser?.close({ silent: true });
52	    await rm(work, { recursive: true, force: true });
53	  }
54	}
55	
56	/** Writes `reel.mp4`, `reel.srt` and `poster.png` into `outDir`. With `audioPath` null the cut carries captions instead of narration. */
57	export async function renderReel(i: { storyboard: Storyboard; timings: LineTiming[]; audioPath: string | null; outDir: string }): Promise<RenderArtifact> {
