1	// Pure text shaping for the scenes: no React, no theme, so it runs under vitest.
2	
3	/** The limits `Scene` in `@dailies/core` already enforces. Scenes clamp to them again because render props arrive unparsed. */
4	export const LIMITS = {
5	  promptQuote: 280,
6	  command: 200,
7	  output: 600,
8	  hunk: 2400,
9	  statLabel: 24,
10	  statValue: 16,
11	  flagQuote: 240,
12	  flagReality: 200,
13	  line: 220,
14	} as const;
15	
16	const ELLIPSIS = '…';
17	
18	/** Cut to `max` characters, ellipsis included. Counts code points so an emoji is never split. */
19	export function clampEnd(text: string, max: number): string {
20	  const chars = Array.from(text);
21	  if (chars.length <= max) return text;
22	  return chars.slice(0, Math.max(0, max - 1)).join('').trimEnd() + ELLIPSIS;
23	}
24	
25	/** Like `clampEnd` but keeps the tail, which is the part of a path worth reading. */
26	export function clampStart(text: string, max: number): string {
27	  const chars = Array.from(text);
28	  if (chars.length <= max) return text;
29	  return ELLIPSIS + chars.slice(chars.length - Math.max(0, max - 1)).join('').trimStart();
30	}
31	
32	const monoLine = (line: string) => line.replace(/\r/g, '').replace(/\t/g, '  ').trimEnd();
33	
34	/**
35	 * The last non-blank lines of a command's output, since that is where a runner prints its verdict.
36	 * When lines are left out, one of the `maxLines` rows is kept free for a marker showing `skipped`.
37	 */
38	export function tailLines(output: string, maxLines: number, maxCols: number): { skipped: number; lines: string[] } {
39	  const all = output.split('\n').map(monoLine).filter((l) => l.trim() !== '');
40	  const keep = all.length <= maxLines ? all.length : Math.max(0, maxLines - 1);
41	  return { skipped: all.length - keep, lines: all.slice(all.length - keep).map((l) => clampEnd(l, maxCols)) };
42	}
43	
44	export interface DiffRow { kind: 'add' | 'del' | 'context' | 'hunk'; text: string }
45	
46	/** Rows of a unified diff without their marker column. Anything in front of the first `@@` is file header and is dropped. */
47	export function parseHunk(hunk: string): DiffRow[] {
48	  const lines = hunk.replace(/\n+$/, '').split('\n').map(monoLine);
49	  const firstHunk = lines.findIndex((l) => l.startsWith('@@'));
50	  const rows: DiffRow[] = [];
51	  for (const line of firstHunk > 0 ? lines.slice(firstHunk) : lines) {
52	    if (line.startsWith('\\')) continue;                        // "\ No newline at end of file"
53	    if (line.startsWith('@@')) rows.push({ kind: 'hunk', text: line });
54	    else if (line.startsWith('+')) rows.push({ kind: 'add', text: line.slice(1) });
55	    else if (line.startsWith('-')) rows.push({ kind: 'del', text: line.slice(1) });
56	    else rows.push({ kind: 'context', text: line.startsWith(' ') ? line.slice(1) : line });
57	  }
58	  return rows;
59	}
60	
61	/**
62	 * At most `max` rows of a patch. A patch that does not fit is shown through the window holding the most
63	 * changed lines (the earliest on a tie), with one of the `max` rows kept free for a marker showing `hidden`.
64	 */
65	export function windowRows(rows: DiffRow[], max: number): { rows: DiffRow[]; hidden: number } {
66	  if (rows.length <= max) return { rows, hidden: 0 };
67	  const size = Math.max(0, max - 1);
68	  const changed = (r: DiffRow) => (r.kind === 'add' || r.kind === 'del' ? 1 : 0);
69	  let best = 0;
70	  let bestCount = -1;
71	  for (let start = 0; start + size <= rows.length; start++) {
72	    const count = rows.slice(start, start + size).reduce((n, r) => n + changed(r), 0);
73	    if (count > bestCount) { best = start; bestCount = count; }
74	  }
75	  return { rows: rows.slice(best, best + size), hidden: rows.length - size };
76	}
77	
78	/**
79	 * A value counting up from zero. `progress` runs 0..1; at 1 the original string is returned untouched,
80	 * so what stays on screen is exactly the value the storyboard carries.
81	 */
82	export function countUp(value: string, progress: number): string {
83	  if (progress >= 1) return value;
84	  const m = /^(\D*?)(\d[\d,]*(?:\.\d+)?)(.*)$/s.exec(value);
85	  if (!m) return value;
86	  const [, prefix, digits, suffix] = m as unknown as [string, string, string, string];
87	  const decimals = digits.includes('.') ? digits.length - digits.indexOf('.') - 1 : 0;
88	  const current = (Number(digits.replace(/,/g, '')) * Math.max(0, progress)).toFixed(decimals);
89	  const [whole, fraction] = current.split('.') as [string, string | undefined];
90	  const grouped = digits.includes(',') ? whole.replace(/\B(?=(\d{3})+$)/g, ',') : whole;
91	  return prefix + grouped + (fraction === undefined ? '' : `.${fraction}`) + suffix;
92	}
93	
94	const WIDE = /[\u1100-\u115f\u2e80-\ua4cf\uac00-\ud7a3\uf900-\ufaff\ufe30-\ufe4f\uff00-\uff60\uffe0-\uffe6]|\p{Extended_Pictographic}/u;
95	const NARROW = /[\p{Ll}\p{N}\p{P}\p{Z}]/u;
96	
97	/**
98	 * The width of `text` counted in average lowercase Latin glyphs, for `fitSize` and `fitLine`.
99	 * Capitals and other scripts set broader than that average, full-width glyphs and emoji broader still;
100	 * counting characters alone would let a Cyrillic or CJK quote overflow its box.
101	 */
102	export function textUnits(text: string): number {
103	  let units = 0;
104	  for (const ch of text) units += WIDE.test(ch) ? 2.4 : ch.charCodeAt(0) < 0x250 && NARROW.test(ch) ? 1 : 1.3;
105	  return units;
106	}
107	
108	/**
109	 * The width of a string in em, in the face it will be set in. In the browser this is a measurement (measure.ts);
110	 * where there is nothing to measure with it is an estimate from `textUnits`.
111	 */
112	export type Em = (text: string) => number;
113	
114	/** An estimate of `Em` for a face whose average lowercase glyph is `advance` em wide. */
115	export const estimateEm = (advance: number): Em => (text) => textUnits(text) * advance;
116	
117	/** Text set in lines: the size it fits at, and whether the end had to be cut off with an ellipsis. */
118	export interface Fitted { size: number; lines: string[]; cut: boolean }
119	
120	/** Characters a line may break after, besides a space. Prose breaks after a hyphen or a slash; a name or a path also after `_` and `.`. */
121	export const BREAKS = { prose: /[-/]/, name: /[-/_.]/ } as const;
122	
123	interface Atom { text: string; width: number; space: boolean }   // `space`: a space comes before it when it does not start a line
124	
125	function atoms(text: string, em: Em, soft: RegExp): Atom[] {
126	  const out: Atom[] = [];
127	  for (const word of text.trim().split(/\s+/).filter(Boolean)) {
128	    let piece = '';
129	    let first = true;
130	    const push = () => { if (piece) out.push({ text: piece, width: em(piece), space: first && out.length > 0 }); first = false; piece = ''; };
131	    for (const ch of word) {
132	      piece += ch;
133	      if (soft.test(ch)) push();
134	    }
135	    push();
136	  }
137	  return out;
138	}
139	
140	/** `split` comes back true when a word was too long for a line and had to be broken inside. */
141	function wrapAtoms(list: Atom[], width: (line: number) => number, em: Em, space: number, split: { any: boolean } = { any: false }): string[] {
142	  const lines: string[] = [];
143	  let line = '';
144	  let used = 0;
145	  const flush = () => { lines.push(line); line = ''; used = 0; };
146	  for (const atom of list) {
147	    const gap = line && atom.space ? space : 0;
148	    if (line && used + gap + atom.width > width(lines.length)) flush();
149	    if (!line && atom.width > width(lines.length)) {
150	      // A single word wider than the line: break it wherever the line ends.
151	      split.any = true;
152	      let rest = Array.from(atom.text);
153	      while (rest.length > 0) {
154	        let take = rest.length;
155	        while (take > 1 && em(rest.slice(0, take).join('')) > width(lines.length)) take--;
156	        line = rest.slice(0, take).join('');
157	        used = em(line);
158	        rest = rest.slice(take);
159	        if (rest.length > 0) flush();
160	      }
161	      continue;
162	    }
163	    line += (line && atom.space ? ' ' : '') + atom.text;
164	    used += (used > 0 ? gap : 0) + atom.width;
165	  }
166	  if (line) lines.push(line);
167	  return lines;
168	}
169	
170	/** `text` broken into lines, line `i` at most `width(i)` em wide. A word too long for a line is split. */
171	export function wrap(text: string, width: (line: number) => number, em: Em, soft: RegExp = BREAKS.prose): string[] {
172	  return wrapAtoms(atoms(text, em, soft), width, em, em('n n') - em('nn'));
173	}
174	
175	/** `line` shortened until it and an ellipsis fit in `width` em. */
176	export function cutToWidth(line: string, width: number, em: Em): string {
177	  const chars = Array.from(line.trimEnd());
178	  while (chars.length > 0 && em(chars.join('').trimEnd() + ELLIPSIS) > width) chars.pop();
179	  return chars.join('').trimEnd() + ELLIPSIS;
180	}
181	
182	/** `line` as it is when it fits in `width` em, otherwise shortened to fit with an ellipsis. */
183	export function clampWidth(line: string, width: number, em: Em): string {
184	  return em(line) <= width ? line : cutToWidth(line, width, em);
185	}
186	
187	const FIT_STEP = 2;
188	const KERN_ROOM = 0.985;   // lines are measured word by word; this leaves room for what kerning adds between them
189	
190	/**
191	 * The largest size from `type.max` down to `type.min` at which `text` fits its room, and the lines it breaks into.
192	 * `room(count, lineHeight)` gives the widths in px open to `count` lines of that height, or null when that many
193	 * lines do not fit at all, so a room can be a box or the chords of a circle. Lines are evened out, not left ragged.
194	 * A word is never broken inside while a smaller size would keep it whole. With `fewest` the text takes as few
195	 * lines as it can before it takes a larger size: right for a name or a label, where a break costs more than size.
196	 * Text that does not fit even at `type.min` is cut with an ellipsis; it is never set smaller.
197	 */
198	export function fitText(
199	  text: string,
200	  type: { max: number; min: number; leading: number },
201	  room: (count: number, lineHeight: number) => number[] | null,
202	  em: Em,
203	  opts: { maxLines?: number; soft?: RegExp; fewest?: boolean } = {},
204	): Fitted {
205	  const maxLines = opts.maxLines ?? 12;
206	  const list = atoms(text, em, opts.soft ?? BREAKS.prose);
207	  const space = em('n n') - em('nn');
208	  if (list.length === 0) return { size: type.max, lines: [], cut: false };
209	
210	  const sizes: number[] = [];
211	  for (let size = type.max; size > type.min; size -= FIT_STEP) sizes.push(size);
212	  sizes.push(type.min);
213	
214	  const attempt = (size: number, count: number): Fitted | 'full' | null => {
215	    const widths = room(count, size * type.leading);
216	    if (!widths) return 'full';
217	    const at = (scale: number) => (i: number) => ((widths[Math.min(i, widths.length - 1)]! * KERN_ROOM) / size) * scale;
218	    const split = { any: false };
219	    const lines = wrapAtoms(list, at(1), em, space, split);
220	    if (lines.length > count || split.any) return null;
221	    // Even the lines out: the narrowest widths that still take the text in as many lines.
222	    let [lo, hi] = [0.4, 1];
223	    let best = lines;
224	    for (let i = 0; i < 7; i++) {
225	      const mid = (lo + hi) / 2;
226	      const tried = { any: false };
227	      const tighter = wrapAtoms(list, at(mid), em, space, tried);
228	      if (tighter.length <= lines.length && !tried.any) { best = tighter; hi = mid; } else lo = mid;
229	    }
230	    return { size, lines: best, cut: false };
231	  };
232	
233	  if (opts.fewest) {
234	    for (let count = 1; count <= maxLines; count++) {
235	      for (const size of sizes) {
236	        const fitted = attempt(size, count);
237	        if (fitted && fitted !== 'full') return fitted;
238	      }
239	    }
240	  } else {
241	    for (const size of sizes) {
242	      for (let count = 1; count <= maxLines; count++) {
243	        const fitted = attempt(size, count);
244	        if (fitted === 'full') break;
245	        if (fitted) return fitted;
246	      }
247	    }
248	  }
249	
250	  const size = type.min;
251	  let count = 0;
252	  while (count < maxLines && room(count + 1, size * type.leading)) count++;
253	  if (count === 0) return { size, lines: [], cut: true };
254	  const widths = room(count, size * type.leading)!;
255	  const width = (i: number) => (widths[Math.min(i, widths.length - 1)]! * KERN_ROOM) / size;
256	  const lines = wrapAtoms(list, width, em, space);
257	  if (lines.length <= count) return { size, lines, cut: false };
258	  const kept = lines.slice(0, count);
259	  kept[count - 1] = cutToWidth(kept[count - 1]!, width(count - 1), em);
260	  return { size, lines: kept, cut: true };
261	}
262	
263	/** A room for `fitText` that is a plain box. */
264	export const boxRoom = (width: number, height: number) => (count: number, lineHeight: number): number[] | null =>
265	  count * lineHeight <= height ? Array<number>(count).fill(width) : null;
266	
267	/** The decisive part of a command's output, for setting large, and the rest of its result. */
268	export interface Decisive { kind: 'count' | 'line' | 'status'; headline: string; detail: string | null }
269	
270	const COUNTED = /(\d[\d,]*)\s+(failed|failing|failures?|errors?|problems?|passed|passing|skipped|pending|todo|warnings?|tests?)\b/gi;
271	const BAD = /^(failed|failing|failures?|errors?|problems?)$/;
272	const GOOD = /^(passed|passing)$/;
273	
274	/**
275	 * What a command's output comes down to. A test runner's summary gives a count (`2 failed`, with `12 passed` as the
276	 * rest); the last such line wins, since that is where a runner prints its totals. Output with no count gives its last
277	 * line. `ok` is the step's own verdict and decides which count leads; it is also all there is when the output is empty.
278	 */
279	export function decisive(output: string, ok: boolean): Decisive {
280	  const lines = output.split('\n').map(monoLine).map((l) => l.trim()).filter(Boolean);
281	  const pairsOf = (line: string) =>
282	    [...line.matchAll(COUNTED)].map((m) => ({ count: m[1]!, word: m[2]!.toLowerCase() })).filter((p) => Number(p.count.replace(/,/g, '')) > 0);
283	  const summary = (test: (word: string) => boolean) => {
284	    for (const line of [...lines].reverse()) {
285	      const pairs = pairsOf(line);
286	      if (pairs.some((p) => test(p.word))) return pairs;
287	    }
288	    return null;
