1	import React, { createContext, useContext, useEffect, useState } from 'react';
2	import { Easing, continueRender, delayRender, interpolate } from 'remotion';
3	import type { Scene } from '@dailies/core';
4	import { fontsReady, theme } from '../theme';
5	import type { Span } from './cues';
6	import type { Shot } from './lens';
7	import { ringAround } from './pencil';
8	import { FACE, emOf, faceStyle, forgetMeasures, type Face } from './measure';
9	import { BREAKS, clampWidth, fitText, sourceRef, splitLast, type Fitted } from './text';
10	
11	const { color, motion, pencil, size, leading, space } = theme;
12	
13	export type SceneOf<T extends Scene['type']> = Extract<Scene, { type: T }>;
14	
15	/** The three layers a scene draws: what is on the film, what is under the glass, and what lies over both. */
16	export interface SceneParts<T extends Scene['type']> {
17	  Film: React.FC<{ scene: SceneOf<T> }>;
18	  Glass: React.FC<{ scene: SceneOf<T> }>;
19	  Over?: React.FC<{ scene: SceneOf<T> }>;
20	}
21	
22	/** What a scene knows about its own time and place while it is on screen. */
23	export interface Clock {
24	  /** Frames since the scene's cut: negative while it is still arriving, past `duration` while it leaves. */
25	  frame: number;
26	  duration: number;
27	  fps: number;
28	  /** Frames after the cut by which the lens has landed on this scene. */
29	  landing: number;
30	  /** The spans of the scene's narration lines. */
31	  lines: Span[];
32	  shot: Shot;
33	  /** The y the scene's content has to stay above: the frame's height, or the top of the caption inset. */
34	  bottom: number;
35	  /** A still: every cue counts as already passed, so the frame shows the scene as it ends up. */
36	  settled: boolean;
37	}
38	
39	export const SceneContext = createContext<Clock | null>(null);
40	
41	const CLAMP = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
42	const ease = Easing.bezier(...motion.ease);
43	
44	/** The scene's clock, with its motion. Every helper but `drawn` has finished by `settle` frames, before the middle of the scene. */
45	export function useScene() {
46	  const clock = useContext(SceneContext);
47	  if (!clock) throw new Error('a scene layer was drawn outside a scene');
48	  const { frame, fps, duration, landing, settled } = clock;
49	  const settle = Math.max(1, duration * motion.settleBy);
50	  const length = Math.max(1, Math.min(motion.enterSec * fps, settle));
51	  const from = (start: number, frames: number) => interpolate(frame, [start, start + Math.max(1, frames)], [0, 1], { ...CLAMP, easing: ease });
52	  // Entrances wait for the lens: they start when it is most of the way there.
53	  const arrive = Math.min(landing * 0.5, Math.max(0, settle - length));
54	  return {
55	    ...clock,
56	    settle,
57	    arrive,
58	    /** Entrance of element `order` in a quick stagger once the lens arrives. */
59	    enter: (order = 0) => from(Math.min(arrive + order * motion.staggerSec * fps, settle - length), length),
60	    /** Entrance of item `index` of `count`, the starts spread from the arrival to the end of the settle window. */
61	    reveal: (index: number, count: number) => from(arrive + ((settle - length - arrive) * index) / Math.max(1, count - 1), length),
62	    /** Eased progress between two shares of the stretch from the arrival to the end of the settle window. */
63	    span: (start: number, end: number) => from(arrive + (settle - arrive) * start, (settle - arrive) * (end - start)),
64	    /** How much of a pencil mark cued at `cue` is drawn, 0..1. */
65	    drawn: (cue: number, seconds: number = motion.drawSec) => (settled ? 1 : interpolate(frame, [cue, cue + Math.max(1, seconds * fps)], [0, 1], CLAMP)),
66	    /** Frames since `cue`; a still is well past every cue (ten seconds, which any spring has long settled in). */
67	    since: (cue: number) => (settled ? 10 * fps : frame - cue),
68	  };
69	}
70	
71	/** True once every face has loaded. Text is measured to be fitted, so nothing is laid out before that. */
72	export function useFonts(): boolean {
73	  const [handle] = useState(() => delayRender('Loading the reel fonts'));
74	  const [ready, setReady] = useState(false);
75	  useEffect(() => {
76	    let live = true;
77	    // A face that fails to load must not hang the render: the fallback family sets the text instead.
78	    fontsReady.catch(() => undefined).then(() => { if (live) { forgetMeasures(); setReady(true); } });
79	    return () => { live = false; };
80	  }, []);
81	  useEffect(() => { if (ready) continueRender(handle); }, [ready, handle]);
82	  return ready;
83	}
