1	import React from 'react';
2	import { fade, theme } from '../theme';
3	import { WIDTH } from './config';
4	import type { Framing, Take } from './lens';
5	import { FACE, faceStyle } from './measure';
6	import { frameBox, framesWithin, stripOf } from './strip';
7	import { useScene } from './ui';
8	
9	const { color, film } = theme;
10	
11	const paint = (id: string) => `url(#${id})`;
12	
13	/** The film's colours: as it lies on the lightbox, or lit from below as it is under the glass. */
14	const PALETTE = {
15	  unlit: { base: color.film.base, frame: color.film.frame, perf: color.film.perf },
16	  lit: { base: color.film.base, frame: color.film.lit, perf: color.film.lit },
17	} as const;
18	type Light = keyof typeof PALETTE;
19	const SLACK = 240;   // px of film drawn past each side of the frame, for the tilt and for motion blur
20	const SMEAR_FROM = 1.5;   // px of travel below which the film is drawn still
21	
22	/**
23	 * The base of the strip with its two rows of perforations and the light on its edges. It runs on past both sides
24	 * of the frame. `smear` is how far the film travels while the shutter is open, in px: each perforation is drawn
25	 * drawn out over that length and thinned to match, which is what motion blur does to it, at no cost of a filter.
26	 */
27	const Band: React.FC<{ view: Framing; lensX: number; id: string; smear: number; light: Light }> = ({ view, lensX, id, smear, light }) => {
28	  const tone = PALETTE[light];
29	  const perf = view.unit / film.perforations;
30	  const height = view.unit * film.height;
31	  const left = lensX + SLACK;
32	  const width = WIDTH + 2 * SLACK;
33	  const hole = { width: view.unit * film.perf.width, height: view.unit * film.perf.height, inset: view.unit * film.perf.inset, radius: view.unit * film.perf.radius };
34	  // Perforations sit at whole numbers of the film's own count, so they travel with it and stay in step across a glide.
35	  const phase = (((-view.takes[0]!.focus % 1) + 1) % 1) * perf;
36	  const rows = [hole.inset, height - hole.inset - hole.height];
37	  const moving = smear > SMEAR_FROM;
38	  // A hole `w` wide drawn out over `d`: a ramp up, a plateau and a ramp down, `w + d` long in all and `w / d` strong at most.
39	  const ramp = Math.min(hole.width, smear) / (hole.width + smear);
40	  const strength = Math.min(1, hole.width / Math.max(smear, 1));
41	  const count = Math.ceil(width / perf) + 2;
42	  return (
43	    <svg width={width} height={height} style={{ position: 'absolute', left: -left, top: -height / 2 }}>
44	      <defs>
45	        <pattern id={id} patternUnits="userSpaceOnUse" x={left + phase} y={0} width={perf} height={height}>
46	          {rows.map((y) => (
47	            <rect key={y} x={(perf - hole.width) / 2} y={y} width={hole.width} height={hole.height} rx={hole.radius} fill={tone.perf} />
48	          ))}
49	        </pattern>
50	        <linearGradient id={`${id}-smear`}>
51	          <stop offset={0} stopColor={tone.perf} stopOpacity={0} />
52	          <stop offset={ramp} stopColor={tone.perf} stopOpacity={strength} />
53	          <stop offset={1 - ramp} stopColor={tone.perf} stopOpacity={strength} />
54	          <stop offset={1} stopColor={tone.perf} stopOpacity={0} />
55	        </linearGradient>
56	      </defs>
57	      <rect width={width} height={height} fill={tone.base} />
58	      {moving ? (
59	        rows.flatMap((y) =>
60	          Array.from({ length: count }, (_, i) => (
61	            <rect key={`${y}-${i}`} x={left + phase + (i - 1 - Math.floor(left / perf)) * perf + (perf - hole.width - smear) / 2} y={y} width={hole.width + smear} height={hole.height} rx={hole.radius} fill={paint(`${id}-smear`)} />
62	          )),
63	        )
64	      ) : (
65	        <rect width={width} height={height} fill={paint(id)} />
