1	import React, { useMemo } from 'react';
2	import { AbsoluteFill, Sequence, interpolate, staticFile, useCurrentFrame, useVideoConfig } from 'remotion';
3	import { Audio } from '@remotion/media';
4	import type { LineTiming, Scene, Storyboard } from '@dailies/core';
5	import { HEIGHT, NARRATION_FILE, type ReelProps } from './config';
6	import { theme } from '../theme';
7	import { buildTimeline, lineAt } from '../timeline';
8	import { lineSpans, stepAt } from './cues';
9	import { Strip } from './Film';
10	import { framing, lensPath, shotOf, type Take } from './lens';
11	import { Loupe } from './Loupe';
12	import { PencilDefs } from './marks';
13	import { FACE, emOf } from './measure';
14	import { stripOf } from './strip';
15	import { LIMITS, boxRoom, clampEnd, fitText } from './text';
16	import { Lines, SceneContext, useFonts, type Clock } from './ui';
17	import { Diff } from './scenes/Diff';
18	import { End } from './scenes/End';
19	import { Flag } from './scenes/Flag';
20	import { Prompt } from './scenes/Prompt';
21	import { Stats } from './scenes/Stats';
22	import { Terminal } from './scenes/Terminal';
23	import { Title } from './scenes/Title';
24	
25	const { color, size, leading, radius, space, layout, motion, film, loupe } = theme;
26	
27	const BLUR_FROM = 0.75;          // px of blur below which content under the glass is left sharp
28	const MAX_DRIFT = 40;            // px the picture may drift from where a scene rests
29	
30	/** The three layers of a scene. */
31	function layers(scene: Scene): { film: React.ReactNode; glass: React.ReactNode; over: React.ReactNode } {
32	  switch (scene.type) {
33	    case 'title': return { film: <Title.Film scene={scene} />, glass: <Title.Glass scene={scene} />, over: Title.Over ? <Title.Over scene={scene} /> : null };
34	    case 'prompt': return { film: <Prompt.Film scene={scene} />, glass: <Prompt.Glass scene={scene} />, over: null };
35	    case 'terminal': return { film: <Terminal.Film scene={scene} />, glass: <Terminal.Glass scene={scene} />, over: null };
36	    case 'diff': return { film: <Diff.Film scene={scene} />, glass: <Diff.Glass scene={scene} />, over: null };
37	    case 'stats': return { film: <Stats.Film scene={scene} />, glass: <Stats.Glass scene={scene} />, over: null };
38	    case 'flag': return { film: <Flag.Film scene={scene} />, glass: <Flag.Glass scene={scene} />, over: Flag.Over ? <Flag.Over scene={scene} /> : null };
39	    case 'end': return { film: <End.Film scene={scene} />, glass: <End.Glass scene={scene} />, over: End.Over ? <End.Over scene={scene} /> : null };
40	  }
41	}
42	
43	/** The line being spoken, in a bar across the inset every narrated scene keeps free for it. */
44	const CaptionBar: React.FC<{ storyboard: Storyboard; timings: LineTiming[]; audioStartFrame: number }> = ({ storyboard, timings, audioStartFrame }) => {
45	  const frame = useCurrentFrame();
46	  const { fps } = useVideoConfig();
47	  const line = lineAt(storyboard, timings, (frame - audioStartFrame) / fps);
48	  if (!line) return null;
49	  const type = { max: size.text.caption, min: size.text.caption, leading: leading.text };
50	  const width = layout.captionWidth - 2 * space.xl;
51	  const fitted = fitText(clampEnd(line.text.replace(/\s+/g, ' ').trim(), LIMITS.line), type, boxRoom(width, layout.captionLines * type.max * type.leading), emOf(FACE.body), { maxLines: layout.captionLines });
52	  const since = frame - (audioStartFrame + line.startSec * fps);
53	  const shown = interpolate(since, [0, motion.enterSec * fps * 0.5], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
54	  return (
55	    <AbsoluteFill style={{ justifyContent: 'flex-end', alignItems: 'center', paddingBottom: layout.captionBottom }}>
56	      <div style={{ padding: `${space.md}px ${space.xl}px`, background: layout.captionFill, border: `${film.edgeWidth}px solid ${layout.captionEdge}`, borderRadius: radius.bar, opacity: shown }}>
57	        <Lines fitted={fitted} face={FACE.body} leading={type.leading} align="center" />
58	      </div>
59	    </AbsoluteFill>
60	  );
61	};
62	
63	export const Reel: React.FC<ReelProps> = ({ storyboard, timings, audio, settled = false }) => {
64	  const frame = useCurrentFrame();
65	  const { fps } = useVideoConfig();
66	  const ready = useFonts();
67	  const captions = !audio;
68	
69	  const plan = useMemo(() => {
70	    const timeline = buildTimeline(storyboard, timings, fps);
71	    const shots = storyboard.scenes.map((scene) => shotOf(scene, captions));
72	    const path = lensPath(timeline, storyboard, { captions });
73	    const spans = storyboard.scenes.map((scene, i) => lineSpans(scene, timings, timeline.scenes[i]!, timeline.audioStartFrame, fps));
74	    return { timeline, shots, path, spans };
75	  }, [storyboard, timings, fps, captions]);
76	  const { timeline, shots, path, spans } = plan;
77	
78	  if (!ready) return null;
79	
80	  const slot = (i: number) => timeline.scenes[i]!;
81	  // Where the lens is along a scene's own frames: its resting point, moved on by the steps a terminal has told so far.
82	  const focusAt = (at: number) => (i: number) =>
83	    shots[i]!.at + film.perforations * stepAt(storyboard.scenes[i]!, spans[i]!, at - slot(i).startFrame, slot(i).durationInFrames, fps, settled);
84	  const view = framing(path, shots, frame, focusAt(frame));
85	
86	  // The picture drifts along the strip while a scene plays; across a glide one scene's drift hands over to the next.
87	  const driftOf = (i: number) => Math.max(-MAX_DRIFT, Math.min(MAX_DRIFT, (-motion.driftPerSec * (frame - slot(i).startFrame - slot(i).durationInFrames / 2)) / fps));
88	  const drift = driftOf(view.lens.from) + (driftOf(view.lens.to) - driftOf(view.lens.from)) * Math.max(0, Math.min(1, view.lens.progress));
89	  const lens = { ...view.lens, x: view.lens.x + drift };
90	
91	  // Motion blur along the film, from how far it moved since the frame before.
92	  const before = framing(path, shots, frame - 1, focusAt(frame - 1));
93	  const perf = view.unit / film.perforations;
94	  const speed = Math.max(0, ...view.takes.map((take) => Math.abs(take.focus - (before.takes.find((t) => t.index === take.index)?.focus ?? take.focus)) * perf));
95	  const smear = speed * motion.shutter;
96	
97	  const clock = (take: Take): Clock => {
98	    const scene = storyboard.scenes[take.index]!;
99	    const arrival = path.transitions[Math.max(0, take.index - 1)];
100	    return {
101	      frame: frame - slot(take.index).startFrame,
102	      duration: slot(take.index).durationInFrames,
103	      fps,
104	      landing: arrival ? arrival.end - arrival.cut : 0,
105	      lines: spans[take.index]!,
106	      shot: take.shot,
107	      bottom: captions && scene.lines.length > 0 ? HEIGHT - layout.captionInset : HEIGHT,
108	      settled,
109	    };
110	  };
111	  const drawn = view.takes.map((take) => ({ take, clock: clock(take), parts: layers(storyboard.scenes[take.index]!) }));
112	
113	  return (
114	    <AbsoluteFill style={{ background: theme.backdrop(lens), color: color.white, overflow: 'hidden' }}>
115	      <PencilDefs />
116	
117	      <div style={{ position: 'absolute', left: lens.x, top: lens.y, width: 0, height: 0 }}>
118	        <Strip view={view} lensX={lens.x} id="perforations" smear={smear}>
119	          {(take) => {
120	            const layer = drawn.find((d) => d.take.index === take.index)!;
121	            return <SceneContext.Provider value={layer.clock}>{layer.parts.film}</SceneContext.Provider>;
122	          }}
123	        </Strip>
124	      </div>
125	      <AbsoluteFill style={{ background: theme.spill(lens) }} />
126	
127	      <Loupe
128	        lens={lens}
129	        transit={1 - Math.max(...view.takes.map((take) => take.presence))}
130	        skirt={<Strip view={view} lensX={lens.x} id="perforations-skirt" smear={smear} />}
131	        passing={<Strip view={{ ...view, unit: view.unit * loupe.passing.magnify }} lensX={lens.x} id="perforations-glass" smear={smear * loupe.passing.magnify} light="lit" />}
132	      >
133	        {drawn.map(({ take, clock: value, parts }) => {
134	          // What is under the glass grows with the lens, passes faster than the film does, and comes into focus as the lens lands.
135	          const passed = (take.shot.at - take.focus) * stripOf(take.shot.unit, take.shot.half).perf * loupe.parallax;
136	          const soft = (1 - take.presence) * loupe.focusBlur;
137	          return (
138	            <SceneContext.Provider key={take.index} value={value}>
139	              <div style={{ position: 'absolute', left: 0, top: 0, width: 0, height: 0, opacity: take.presence, transform: `scale(${lens.scale / take.shot.lens.scale}) translateX(${passed}px)`, filter: soft > BLUR_FROM ? `blur(${soft}px)` : undefined }}>
140	                {parts.glass}
141	              </div>
142	            </SceneContext.Provider>
143	          );
144	        })}
145	      </Loupe>
146	
147	      {/* What lies over the film (titles, the verdict pill) is on the lightbox too, and travels with it. */}
148	      {drawn.map(({ take, clock: value, parts }) =>
149	        parts.over ? (
150	          <SceneContext.Provider key={take.index} value={value}>
151	            <AbsoluteFill style={{ opacity: take.presence, transform: `translateX(${drift + (take.shot.at - take.focus) * perf}px)` }}>{parts.over}</AbsoluteFill>
152	          </SceneContext.Provider>
153	        ) : null,
154	      )}
155	
156	      {audio ? (
157	        <Sequence name="narration" from={timeline.audioStartFrame} layout="none">
158	          <Audio src={staticFile(NARRATION_FILE)} />
159	        </Sequence>
160	      ) : (
161	        <CaptionBar storyboard={storyboard} timings={timings} audioStartFrame={timeline.audioStartFrame} />
162	      )}
