1	// Grease-pencil geometry: pure, so it runs under vitest. marks.tsx strokes these paths and animates them.
2	// Every path is a deterministic function of its size and seed; a render never differs from the one before.
3	
4	export type MarkKind = 'ring' | 'cross' | 'dashed' | 'question';
5	
6	/** A small seeded generator (mulberry32), so a mark wobbles the same way on every frame. */
7	function random(seed: number): () => number {
8	  let a = (Math.imul(seed | 0, 0x9e3779b1) + 0x7f4a7c15) >>> 0;
9	  return () => {
10	    a = (a + 0x6d2b79f5) >>> 0;
11	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
12	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
13	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
14	  };
15	}
16	
17	type Point = readonly [number, number];
18	const n1 = (n: number) => Math.round(n * 10) / 10;
19	
20	/** A smooth curve through `points` (Catmull-Rom, written as cubic Béziers). */
21	function through(points: Point[]): string {
22	  let d = `M${n1(points[0]![0])},${n1(points[0]![1])}`;
23	  for (let i = 0; i < points.length - 1; i++) {
24	    const p0 = points[Math.max(i - 1, 0)]!;
25	    const p1 = points[i]!;
26	    const p2 = points[i + 1]!;
27	    const p3 = points[Math.min(i + 2, points.length - 1)]!;
28	    d += ` C${n1(p1[0] + (p2[0] - p0[0]) / 6)},${n1(p1[1] + (p2[1] - p0[1]) / 6)} ${n1(p2[0] - (p3[0] - p1[0]) / 6)},${n1(p2[1] - (p3[1] - p1[1]) / 6)} ${n1(p2[0])},${n1(p2[1])}`;
29	  }
30	  return d;
31	}
32	
33	const RING_STEPS = 32;
34	
35	/**
36	 * A loop drawn by hand inside a `width` by `height` box centred on the origin. It starts at the left, goes over
37	 * the top, and with `turns` above 1 runs past its own start the way a pencil does when it closes a circle.
38	 */
39	export function ringPath(width: number, height: number, seed: number, turns = 1.14): string {
40	  const r = random(seed);
41	  const phase = [r() * Math.PI * 2, r() * Math.PI * 2] as const;
42	  const wobble = [0.03 * (0.7 + r() * 0.6), 0.02 * (0.7 + r() * 0.6)] as const;
43	  const tilt = -0.07 + r() * 0.06;
44	  const start = Math.PI * (0.86 + r() * 0.12);
45	  const drift = turns > 1 ? -0.1 : 0;   // an open loop spirals inwards a little, so its end sits inside its start
46	  const points: Point[] = [];
47	  for (let i = 0; i <= RING_STEPS; i++) {
48	    const t = i / RING_STEPS;
49	    const a = start + Math.PI * 2 * turns * t;
50	    const k = 1 + wobble[0] * Math.sin(a + phase[0]) + wobble[1] * Math.sin(a * 2.3 + phase[1]) + drift * (t - 0.5);
51	    const x = (Math.cos(a) * width * k) / 2;
52	    const y = (Math.sin(a) * height * k) / 2;
53	    points.push([x * Math.cos(tilt) - y * Math.sin(tilt), x * Math.sin(tilt) + y * Math.cos(tilt)]);
54	  }
55	  return through(points);
56	}
57	
58	/** Two strokes through a `width` by `height` box centred on the origin, each a little bowed and off its corners. */
59	export function crossPaths(width: number, height: number, seed: number): [string, string] {
60	  const r = random(seed);
61	  const j = (range: number) => (r() - 0.5) * range;
62	  const [x, y] = [width / 2, height / 2];
63	  const stroke = (side: 1 | -1) =>
64	    through([
65	      [-side * x + j(width * 0.05), -y + j(height * 0.08)],
66	      [-side * x * 0.36, -y * 0.38 + j(height * 0.08)],
67	      [side * x * 0.3, y * 0.26 + j(height * 0.08)],
68	      [side * x + j(width * 0.05), y + j(height * 0.08)],
69	    ]);
70	  return [stroke(1), stroke(-1)];
71	}
72	
73	/** A question mark `height` tall centred on the origin: the hook, then the dot. */
74	export function questionPaths(height: number): [string, string] {
75	  const s = height / 100;
76	  const p = (x: number, y: number) => `${n1(x * s)},${n1(y * s)}`;
77	  return [`M${p(-23, -23)} C${p(-25, -57)} ${p(27, -59)} ${p(26, -27)} C${p(25, -6)} ${p(1, -5)} ${p(0, 19)}`, `M${p(-1, 43)} L${p(1, 45)}`];
78	}
79	
80	/** The strokes of a mark in the order a hand would draw them. */
81	export function markPaths(kind: MarkKind, width: number, height: number, seed: number): string[] {
82	  switch (kind) {
83	    case 'ring': return [ringPath(width, height, seed)];
84	    case 'dashed': return [ringPath(width, height, seed, 1)];
85	    case 'cross': return crossPaths(width, height, seed);
86	    case 'question': return questionPaths(height);
87	  }
88	}
89	
90	/**
91	 * The dash array that shows the first `progress` of a dashed stroke whose length is normalised to 1:
92	 * whole dashes, the one being drawn, then nothing.
93	 */
94	export function dashesDrawn(progress: number, count: number, fill: number): number[] {
95	  const period = 1 / count;
96	  const dash = period * fill;
97	  const drawn = Math.max(0, Math.min(1, progress));
98	  const whole = Math.floor(drawn / period);
99	  const pattern: number[] = [];
100	  for (let i = 0; i < whole; i++) pattern.push(dash, period - dash);
101	  const part = Math.min(dash, drawn - whole * period);
102	  // A dash of no length would still leave a dot under a round cap, so the pattern ends on a gap instead.
103	  if (part > 0 || pattern.length === 0) pattern.push(part, 2);
104	  else pattern[pattern.length - 1]! += 2;
105	  return pattern;
106	}
107	
108	export type EndMark = 'ring' | 'cross' | 'question';
109	const END_MARK_CAP = 16;
110	const END_ORDER: EndMark[] = ['ring', 'cross', 'question'];
111	
112	/**
113	 * One mark per claim for the end card: rings for verified, crosses for flagged, question marks for unverified,
114	 * in that order. More than sixteen claims are shown as sixteen marks in the proportions of the three kinds,
115	 * never dropping a kind that occurred, and `overflow` is how many claims have no mark of their own.
116	 */
117	export function endMarks(counts: { verified: number; flagged: number; unverified: number }): { marks: EndMark[]; overflow: number } {
118	  const whole = (n: number) => (Number.isFinite(n) ? Math.max(0, Math.floor(n)) : 0);
119	  const claims = [whole(counts.verified), whole(counts.flagged), whole(counts.unverified)];
120	  const total = claims.reduce((a, b) => a + b, 0);
121	  const shown = total <= END_MARK_CAP ? claims : claims.map((n) => (n === 0 ? 0 : Math.max(1, Math.floor((n * END_MARK_CAP) / total))));
122	  const sum = () => shown.reduce((a, b) => a + b, 0);
123	  const owed = (i: number) => (claims[i]! * END_MARK_CAP) / total - shown[i]!;
124	  while (sum() < Math.min(total, END_MARK_CAP)) {
125	    const i = [0, 1, 2].filter((k) => shown[k]! < claims[k]!).reduce((best, k) => (owed(k) > owed(best) ? k : best));
126	    shown[i]! += 1;
127	  }
128	  while (sum() > END_MARK_CAP) shown[shown.indexOf(Math.max(...shown))]! -= 1;
129	  return { marks: END_ORDER.flatMap((kind, i) => Array<EndMark>(shown[i]!).fill(kind)), overflow: total - sum() };
130	}
