132	/**
133	 * The box of a ring that goes round a block of centred lines `widths` px wide, set `lineHeight` px apart, standing
134	 * `pad` px off them. `ink` is how tall the letters of a line are: the pencil has to clear the ends of the letters,
135	 * not the corners of the line boxes, or a ring round a single word comes out far wider than a hand would draw it.
136	 * The ellipse is as tall as the inked block plus its padding, and wide enough to clear both ends of every line.
137	 */
138	export function ringAround(widths: number[], lineHeight: number, ink: number, pad: { x: number; y: number }): { width: number; height: number } {
139	  const half = (widths.length * lineHeight) / 2;
140	  const b = half - (lineHeight - ink) / 2 + pad.y;
