1	// Where the loupe is at every frame: pure, so it runs under vitest and in the browser alike.
2	// A scene declares a shot (where the lens rests, how large, over what film); `lensPath` strings the resting
3	// places together with a glide across every cut; `framing` adds the film that passes under the lens meanwhile.
4	import { measureSpring, spring } from 'remotion';
5	import type { Scene, Storyboard } from '@dailies/core';
6	import type { Timeline } from '../timeline';
7	import { theme } from '../theme';
8	import { HEIGHT, WIDTH } from './config';
9	import { MAX_STEPS } from './cues';
10	import { endMarks } from './pencil';
11	import { stripOf } from './strip';
12	
13	const { shot, loupe, layout, motion, film } = theme;
14	
15	/** A resting place: the centre of the lens in px, its scale (1 is a 276 px glass) and the turn of its barrel in degrees. */
16	export interface LensRest { x: number; y: number; scale: number; turn: number }
17	
18	/** The lens at one frame. At rest `from` and `to` are the same scene; in a glide `progress` runs from 0 towards 1. */
19	export interface LensState extends LensRest { from: number; to: number; progress: number }
20	
21	export interface LensPath {
22	  /** One resting place per scene, in scene order. */
23	  rests: LensRest[];
24	  /** One glide per cut: it leaves at `start`, is half way at `cut` and has landed by `end`. */
25	  transitions: { start: number; cut: number; end: number }[];
26	  at(frame: number): LensState;
27	}
28	
29	/** What a scene declares: where the lens rests and the film it rests on. */
30	export interface Shot {
31	  lens: LensRest;
32	  /** Screen px of the pitch of a full frame under this lens. */
33	  unit: number;
34	  /** Portrait half-frames instead of full landscape ones. */
35	  half: boolean;
36	  /** Perforations from the start of the scene's first frame to the point under the centre of the lens. */
37	  at: number;
38	  /** The first and the last frame the scene puts content on; every other frame of its stretch is greeked. */
39	  frames: readonly [number, number];
40	}
41	
42	const ramp = (t: number, from: number, to: number) => Math.max(0, Math.min(1, (t - from) / (to - from)));
43	const MAX_STATS = shot.stats.scale.length;
44	const NONE = [0, -1] as const;
45	const OVERFLOW_SLOTS = 2.5;   // frames of room the `+n` after the end card's marks takes
46	
47	function statsShot(count: number): Omit<Shot, 'lens' | 'frames'> & { x: number; scale: number } {
48	  const n = Math.max(1, Math.min(MAX_STATS, count));
49	  const scale = shot.stats.scale[n - 1]!;
50	  const reach = loupe.skirt.outer * scale;
51	  // A single value sits under a centred lens. With more, the lens moves to the head of the strip and the
52	  // remaining values start right where its skirt ends.
53	  if (n === 1) return { x: WIDTH / 2, scale, unit: shot.stats.maxPitch * 2, half: true, at: film.perforations / 4 };
54	  const x = reach - shot.stats.bleed[n - 1]!;
55	  const clear = reach + shot.stats.gap;
56	  const pitch = Math.min(shot.stats.maxPitch, (WIDTH - layout.margin / 4 - x - clear) / (n - 1));
57	  return { x, scale, unit: pitch * 2, half: true, at: film.perforations / 2 - clear / (pitch / (film.perforations / 2)) };
58	}
59	
60	/** The pitch of the small frames on the end card and where the marks stop, for `frames` marks and maybe a `+n` after them. */
61	export function endStrip(frames: number, overflow: boolean): { pitch: number; marksEnd: number } {
62	  const slots = frames + (overflow ? OVERFLOW_SLOTS : 0);
63	  const pitch = slots * shot.end.pitch <= shot.end.reach + shot.end.pitch ? shot.end.pitch : Math.max(shot.end.minPitch, shot.end.reach / slots);
64	  const lensEdge = shot.end.x - loupe.skirt.outer * shot.end.scale + shot.end.overlap;
65	  return { pitch, marksEnd: lensEdge - (overflow ? OVERFLOW_SLOTS * pitch : 0) };
66	}
67	
68	/** The shot of a scene. In a captions cut a narrated scene sits higher, clear of the caption bar. */
69	export function shotOf(scene: Scene, captions = false): Shot {
70	  const lift = captions && scene.lines.length > 0 ? layout.captionInset / 2 : 0;
71	  const centre = film.perforations / 2;
72	  switch (scene.type) {
73	    case 'title': return { lens: { x: shot.title.x, y: shot.title.y, scale: shot.title.scale, turn: shot.title.turn }, unit: shot.title.unit, half: false, at: centre, frames: NONE };
74	    case 'prompt': return { lens: { x: shot.prompt.x, y: shot.prompt.y - lift, scale: shot.prompt.scale, turn: shot.prompt.turn }, unit: shot.prompt.unit, half: false, at: centre, frames: [0, 0] };
75	    case 'terminal': {
76	      const steps = Math.min(MAX_STEPS, scene.steps.length);
77	      const frames = [0, steps - 1] as const;
78	      // A single step has the frame to itself: the lens sits in the middle of it, and larger.
79	      if (steps <= 1) return { lens: { x: shot.terminal.alone.x, y: shot.terminal.y - lift, scale: shot.terminal.alone.scale, turn: shot.terminal.turn }, unit: shot.terminal.unit, half: false, at: centre, frames };
80	      return { lens: { x: shot.terminal.x, y: shot.terminal.y - lift, scale: shot.terminal.scale, turn: shot.terminal.turn }, unit: shot.terminal.unit, half: false, at: shot.terminal.at, frames };
81	    }
82	    case 'diff': return { lens: { x: shot.diff.x, y: shot.diff.y - lift, scale: shot.diff.scale, turn: shot.diff.turn }, unit: shot.diff.unit, half: false, at: centre, frames: [0, 0] };
83	    case 'stats': {
84	      const s = statsShot(scene.items.length);
85	      return { lens: { x: s.x, y: shot.stats.y - lift, scale: s.scale, turn: shot.stats.turn }, unit: s.unit, half: true, at: s.at, frames: [0, Math.min(MAX_STATS, scene.items.length) - 1] };
86	    }
87	    case 'flag': {
88	      // The quote is frame 0; the lens rests on the frame after it. A long record gets a larger glass, which
89	      // grows away from the quote so the quote's frame stays where it is.
90	      const scale = shot.flag.scale + shot.flag.grow * ramp(scene.reality.length, shot.flag.short, shot.flag.long);
91	      const x = shot.flag.x + loupe.skirt.outer * (scale - shot.flag.scale);
92	      const at = film.perforations + centre + (x - shot.flag.x) / (shot.flag.unit / film.perforations);
93	      return { lens: { x, y: shot.flag.y - lift, scale, turn: shot.flag.turn }, unit: shot.flag.unit, half: false, at, frames: [0, 1] };
94	    }
95	    case 'end': {
96	      const { marks, overflow } = endMarks(scene);
97	      const { pitch, marksEnd } = endStrip(marks.length, overflow > 0);
98	      const per = film.perforations / 2;
99	      return { lens: { x: shot.end.x, y: shot.end.y, scale: shot.end.scale, turn: shot.end.turn }, unit: pitch * 2, half: true, at: marks.length * per + (shot.end.x - marksEnd) / (pitch / per), frames: NONE };
100	    }
101	  }
102	}
103	
104	// The glide: a spring that follows a short ramp instead of a step, so the lens leaves softly and still settles
105	// like a spring. Tabulated once; a transition reads it through a time warp that puts the cut at half way.
106	const GLIDE = (() => {
107	  const { config, rampFrames } = motion.glide;
108	  const fps = 30;
109	  const length = measureSpring({ fps, config, threshold: 0.002 }) + rampFrames;
110	  const raw = Array.from({ length: length + 1 }, (_, f) => {
111	    let sum = 0;
112	    for (let j = 0; j < rampFrames; j++) sum += f - j <= 0 ? 0 : spring({ frame: f - j, fps, config });
113	    return sum / rampFrames;
114	  });
115	  const table = raw.map((v) => v / raw[length]!);
116	  const after = table.findIndex((v) => v >= 0.5);
117	  const half = after - 1 + (0.5 - table[after - 1]!) / (table[after]! - table[after - 1]!);
118	  return { table, length, half };
119	})();
120	
121	function glideAt(time: number): number {
122	  const t = Math.max(0, Math.min(GLIDE.length, time));
123	  const i = Math.min(GLIDE.length - 1, Math.floor(t));
124	  return GLIDE.table[i]! + (GLIDE.table[i + 1]! - GLIDE.table[i]!) * (t - i);
125	}
126	
127	const mix = (a: number, b: number, t: number) => a + (b - a) * t;
128	
129	/**
130	 * The path of the lens through a reel: one resting place per scene and a glide over every cut.
131	 * The glide starts before the cut and lands inside the settle window of the scene it enters, so the lens
132	 * is still again well before the middle of that scene.
133	 */
134	export function lensPath(timeline: Timeline, storyboard: Storyboard, opts: { captions?: boolean } = {}): LensPath {
135	  const rests = storyboard.scenes.map((scene) => shotOf(scene, opts.captions ?? false).lens);
136	  const transitions = timeline.scenes.slice(1).map((into, i) => {
137	    const out = timeline.scenes[i]!;
138	    const lead = Math.min(Math.round(motion.glide.leadSec * timeline.fps), Math.floor(out.durationInFrames / 2));
139	    const follow = Math.min(Math.round(motion.glide.followSec * timeline.fps), Math.floor(into.durationInFrames * motion.settleBy));
140	    return { start: into.startFrame - lead, cut: into.startFrame, end: into.startFrame + follow };
141	  });
142	
143	  const resting = (i: number): LensState => ({ ...rests[i]!, from: i, to: i, progress: 0 });
144	  const at = (frame: number): LensState => {
145	    let index = 0;
146	    for (const [i, t] of transitions.entries()) {
147	      if (frame >= t.end) { index = i + 1; continue; }
148	      if (frame <= t.start) break;
149	      const time = frame <= t.cut
150	        ? ((frame - t.start) / (t.cut - t.start)) * GLIDE.half
151	        : GLIDE.half + ((frame - t.cut) / (t.end - t.cut)) * (GLIDE.length - GLIDE.half);
152	      const progress = glideAt(time);
153	      const [a, b] = [rests[i]!, rests[i + 1]!];
154	      return { x: mix(a.x, b.x, progress), y: mix(a.y, b.y, progress), scale: mix(a.scale, b.scale, progress), turn: mix(a.turn, b.turn, progress), from: i, to: i + 1, progress };
155	    }
156	    return resting(index);
157	  };
158	  return { rests, transitions, at };
159	}
160	
161	/** The share of the frame the glass covers, 0..1. The lit glass is what keeps a frame of the dark room from reading as black. */
162	export function glassShare(lens: { x: number; y: number; scale: number }): number {
163	  const r = loupe.glass * lens.scale;
164	  const rows = 240;
165	  let area = 0;
166	  for (let i = 0; i < rows; i++) {
167	    const y = ((i + 0.5) / rows) * HEIGHT;
168	    const dy = y - lens.y;
169	    if (Math.abs(dy) >= r) continue;
170	    const half = Math.sqrt(r * r - dy * dy);
171	    area += Math.max(0, Math.min(WIDTH, lens.x + half) - Math.max(0, lens.x - half)) * (HEIGHT / rows);
172	  }
173	  return area / (WIDTH * HEIGHT);
174	}
175	
176	/**
177	 * One scene's film as the camera sees it: how far along its own frames the lens is (`focus`, in perforations),
178	 * how much of what the scene put on the film shows (`presence`) and how much of its bare frames (`frames`).
179	 */
180	export interface Take { index: number; shot: Shot; focus: number; presence: number; frames: number }
181	
182	/** The lens and the film under it at one frame. In a glide both scenes are on the strip, one leaving and one arriving. */
183	export interface Framing { lens: LensState; unit: number; takes: Take[] }
184	
185	/**
186	 * Perforations of film that pass under the lens between two scenes: about `motion.travel` px of it, adjusted
187	 * so that the perforations of the scene being left run on into those of the scene being entered.
188	 */
189	export function travel(a: Shot, focusA: number, b: Shot): number {
190	  const mean = Math.sqrt(stripOf(a.unit, a.half).perf * stripOf(b.unit, b.half).perf);
191	  const whole = Math.round(motion.travel / mean);
192	  return whole + ((((b.at - focusA - whole) % 1) + 1) % 1);
193	}
194	
195	const OPENING_PERFORATIONS = 10;   // how far the film is pulled in under the lens as the reel opens
196	
197	/**
198	 * The framing at `frame`. `focusOf(i)` is where the lens is along scene `i`'s own frames right now; a scene that
199	 * advances its strip while it plays (the terminal) moves that, every other scene leaves it at its shot's `at`.
200	 */
201	export function framing(path: LensPath, shots: Shot[], frame: number, focusOf: (index: number) => number): Framing {
202	  const lens = path.at(frame);
203	  if (lens.from === lens.to) {
204	    const shot = shots[lens.from]!;
205	    // The reel opens on the second half of a glide: the film is pulled into place under a lens that is already waiting.
206	    const open = path.transitions[0] ? Math.max(1, path.transitions[0].end - path.transitions[0].cut) : 1;
207	    const e = lens.from === 0 && frame < open ? glideAt(GLIDE.half + (Math.max(0, frame) / open) * (GLIDE.length - GLIDE.half)) : 1;
208	    const away = (1 - e) * 2 * OPENING_PERFORATIONS;
209	    return { lens, unit: shot.unit, takes: [{ index: lens.from, shot, focus: focusOf(lens.from) - away, presence: ramp(e, 0.5, 0.92), frames: 1 }] };
210	  }
211	  const [a, b] = [shots[lens.from]!, shots[lens.to]!];
212	  const e = lens.progress;
213	  const left = focusOf(lens.from);
214	  const distance = travel(a, left, b);
215	  return {
216	    lens,
217	    unit: a.unit * (b.unit / a.unit) ** e,
218	    takes: [
219	      { index: lens.from, shot: a, focus: left + e * distance, presence: 1 - ramp(e, 0.04, 0.34), frames: 1 - ramp(e, 0.3, 0.62) },
220	      { index: lens.to, shot: b, focus: focusOf(lens.to) - (1 - e) * distance, presence: ramp(e, 0.5, 0.92), frames: ramp(e, 0.38, 0.7) },
221	    ],
222	  };
223	}
224	
225	/**
226	 * The room for text under the glass at a resting place: a block centred on (`cx`, `cy`) from the centre of the
227	 * lens, at most `height` tall, and `width(top, bottom)` wide for a line between those two heights of the block.
228	 * It keeps `loupe.rim` clear of the edge of the glass and of the frame, and stays above `bottom`.
229	 */
230	export interface GlassRoom {
231	  cx: number;
232	  cy: number;
233	  height: number;
234	  width(top: number, bottom: number): number;
235	  /** How far the glass runs to the left and to the right of the block's centre at height `y` of the block. */
236	  reach(y: number): readonly [number, number];
237	}
238	
239	export function glassRoom(rest: LensRest, bottom: number = HEIGHT, rim: number = loupe.rim): GlassRoom {
240	  const r = loupe.glass * rest.scale - rim;
241	  const side = layout.margin / 2;
242	  const top = Math.max(-r, side - rest.y);
243	  const floor = Math.min(r, bottom - side / 2 - rest.y);
244	  const cy = (top + floor) / 2;
245	  const reach = (y: number) => {
246	    const half = Math.sqrt(Math.max(0, r * r - y * y));
247	    return [Math.max(-half, side - rest.x), Math.min(half, WIDTH - side - rest.x)] as const;
248	  };
249	  const [l0, r0] = reach(cy);
250	  const cx = (l0 + r0) / 2;
251	  return {
252	    cx,
253	    cy,
254	    height: Math.max(0, floor - top),
255	    reach: (y) => { const [l, rr] = reach(cy + y); return [cx - l, rr - cx] as const; },
256	    width: (t, b) => {
257	      // The narrowest of the chords at the two edges of the line, measured symmetrically about the block's centre.
258	      const spans = [reach(cy + t), reach(cy + b)];
259	      return Math.max(0, 2 * Math.min(...spans.map(([l, rr]) => Math.min(cx - l, rr - cx))));
260	    },
261	  };
262	}
263	
264	/**
265	 * A room for `fitText` inside a glass: the lines sit in a block that also holds `above` px over them and `below`
266	 * px under, centred in the glass. No line is given more than `cap` px, which keeps a measure readable.
267	 */
268	export function linesRoom(room: GlassRoom, above = 0, below = 0, cap = Infinity) {
269	  return (count: number, lineHeight: number): number[] | null => {
270	    const height = above + count * lineHeight + below;
271	    if (height > room.height) return null;
272	    const top = -height / 2 + above;
273	    const widths = Array.from({ length: count }, (_, i) => Math.min(cap, room.width(top + i * lineHeight, top + (i + 1) * lineHeight)));
274	    return widths.every((w) => w > 0) ? widths : null;
275	  };
276	}
