1	import { spring } from 'remotion';
2	import { theme } from '../../theme';
3	import { cueFrame, itemSpans } from '../cues';
4	import { OnFrame } from '../Film';
5	import { glassRoom, linesRoom } from '../lens';
6	import { Mark } from '../marks';
7	import { FACE, emOf, faceStyle } from '../measure';
8	import { frameBox, stripOf } from '../strip';
9	import { LIMITS, boxRoom, clampEnd, clampWidth, closingCount } from '../text';
10	import { GlassBlock, Lines, ROLES, Type, fitRef, fitRoles, heightOf, ringOf, useScene, widthOf, type SceneOf, type SceneParts } from '../ui';
11	
12	const { color, size, leading, space, film, loupe, dim, motion, radius, shot } = theme;
13	
14	const WORD = { contradicted: 'CONTRADICTED', stale: 'STALE' } as const;
15	// The cross takes this share of the quote's frame; a ring stands this far off what it holds, in px.
16	const CROSS = { width: 0.94, height: 0.7 };
17	const RING = { x: 56, y: 40 };
18	const RING_RIM = 40;   // extra margin the reality keeps from the rim, so its ring stays on the glass
19	const RECORD_RING = { x: 22, y: 34 };   // how far the ring round the whole record stands off its lines
20	const RING_EDGE = 14;  // the closest a ring comes to the edge of the glass
21	const COUNT_RING = { x: 28, y: 32 };    // how far the ring round a closing count stands off it
22	const COUNT_GAP = space.xl + space.xs;  // between what leads up to the count and the count, with room for that ring
23	
24	/** When the three beats of the scene land: the pencil over the quote, the pill, the ring around the record. */
25	function useCues(scene: SceneOf<'flag'>) {
26	  const m = useScene();
27	  // The first line tells the claim, the last tells the record; a single line is shared between them.
28	  const [claim, record] = itemSpans([0, Math.max(0, scene.lines.length - 1)], m.lines, { start: 0, end: m.duration });
29	  const quote = cueFrame(claim!, m.fps, m.landing);
30	  const pill = quote + motion.drawSec * m.fps;
31	  return { m, quote, pill, record: Math.max(cueFrame(record!, m.fps, m.landing), pill) };
32	}
33	
34	/** Where the centre of the pill is along the strip, from the centre of a lens of `scale`: just inside the lens's near edge. */
35	const pillX = (scale: number) => shot.flag.pill.x - loupe.skirt.outer * scale;
36	
37	/** The verdict pill: its word and its size in px. */
38	function pillOf(verdict: SceneOf<'flag'>['verdict']) {
39	  const word = WORD[verdict];
40	  return { word, width: emOf(FACE.verdict)(word) * size.display.verdict + 2 * shot.flag.pill.pad, height: size.display.verdict * shot.flag.pill.height };
41	}
42	
43	/** The entry the claim was made in: the one the first line cites, or failing that the claim's own id. Set to fit `width` px. */
44	const source = (scene: SceneOf<'flag'>, width: number): string => {
45	  const cited = scene.lines.flatMap((line) => line.evidence).find((e) => e.type === 'entry');
46	  return cited?.type === 'entry' ? fitRef(cited.entryId, width) : clampWidth(`claim ${scene.claimId}`, width / size.code.ref, emOf(FACE.code));
47	};
48	
49	export const Flag: SceneParts<'flag'> = {
50	  Film: ({ scene }) => {
51	    const { m, quote: cue } = useCues(scene);
52	    const strip = stripOf(m.shot.unit, m.shot.half);
53	    const box = frameBox(strip, m.shot.at, 0);
54	    const pad = space.xxl;
55	    const label = size.code.ref * leading.code;
56	    const width = box.width - 2 * pad;
