1	import { theme } from '../../theme';
2	import { OnFrame } from '../Film';
3	import { glassRoom, linesRoom } from '../lens';
4	import { Mark } from '../marks';
5	import { FACE, emOf } from '../measure';
6	import { endMarks, type EndMark } from '../pencil';
7	import { frameBox, stripOf } from '../strip';
8	import { boxRoom, clampEnd, fitText } from '../text';
9	import { GlassBlock, Lines, RepoName, Rise, Type, fitRepo, useScene, type SceneParts } from '../ui';
10	
11	const { color, size, leading, space, layout, loupe, dim, motion, film } = theme;
12	
13	const REPO_CHARS = 80;
14	const HERO_LINES = 3;
15	// The size of each mark as a share of the pitch of its frame, and its stroke.
16	const SHAPE: Record<EndMark, { width: number; height: number }> = { ring: { width: 0.6, height: 0.76 }, cross: { width: 0.72, height: 1 }, question: { width: 0.5, height: 0.8 } };
17	const STROKE = { share: 0.062, min: 4, max: 9 };
18	const TALLY_MARK = 52;     // px of the mark in front of each count
19	const TALLY_STROKE = 6.5;
20	const STAGGER = 4;         // frames between two marks drawing on
21	
22	const stroke = (pitch: number) => Math.max(STROKE.min, Math.min(STROKE.max, pitch * STROKE.share));
23	
24	export const End: SceneParts<'end'> = {
25	  Film: ({ scene }) => {
26	    const m = useScene();
27	    const { marks, overflow } = endMarks(scene);
28	    const strip = stripOf(m.shot.unit, m.shot.half);
29	    const box = frameBox(strip, m.shot.at, 0);
30	    // The scene is silent, so the marks are not cued by a line: they follow one another once the lens has landed.
31	    const draw = motion.drawSec * m.fps;
32	    const step = Math.min(STAGGER, Math.max(0, m.settle - m.arrive - draw) / Math.max(1, marks.length));
33	    const after = frameBox(strip, m.shot.at, marks.length);
34	    return (
35	      <>
36	        {marks.map((kind, i) => (
37	          <OnFrame key={i} k={i}>
38	            <Mark kind={kind} x={box.width / 2} y={box.height / 2} width={strip.pitch * SHAPE[kind].width} height={strip.pitch * SHAPE[kind].height} seed={20 + i} weight={stroke(strip.pitch)} progress={m.drawn(m.arrive + i * step)} />
39	          </OnFrame>
40	        ))}
41	        {overflow > 0 ? (
42	          <Type face={FACE.text} size={size.text.tally} leading={leading.solid} style={{ position: 'absolute', left: after.left + space.xs, top: -size.text.tally / 2, opacity: m.span(0.6, 1), WebkitTextStroke: `${space.sm}px ${color.film.base}`, paintOrder: 'stroke fill' }}>{`+${overflow}`}</Type>
43	        ) : null}
44	      </>
45	    );
46	  },
47	
48	  Glass: () => {
49	    const { shot } = useScene();
50	    const room = glassRoom(shot.lens);
51	    const mark = fitText('Dailies', { ...size.display.wordmark, leading: leading.solid }, linesRoom(room), emOf(FACE.heavy), { maxLines: 1 });
52	    return (
53	      <GlassBlock at={room}>
54	        <Lines fitted={mark} face={FACE.heavy} leading={leading.solid} align="center" />
55	      </GlassBlock>
56	    );
57	  },
58	
59	  Over: ({ scene }) => {
60	    const m = useScene();
61	    const strip = stripOf(m.shot.unit, m.shot.half);
62	    const width = m.shot.lens.x - loupe.skirt.outer * m.shot.lens.scale - layout.margin - space.xxl;
63	    // The name sits in the room above the strip and the counts in the room under it. The strip is tilted, so at
64	    // the left of the frame, where both of them are, it lies lower than at the lens.
65	    const drop = Math.tan((-film.tilt * Math.PI) / 180) * (m.shot.lens.x - layout.margin);
66	    const above = m.shot.lens.y + drop - strip.height / 2;
67	    const below = m.shot.lens.y + drop + strip.height / 2;
68	    const hero = above - layout.margin - space.xl;
69	    const fit = fitRepo(clampEnd(scene.repo, REPO_CHARS), size.display.hero, (above, below) => boxRoom(width, hero - above - below), HERO_LINES);
70	    const tallies: { kind: EndMark; count: number; text: string }[] = [
71	      { kind: 'ring', count: scene.verified, text: `${scene.verified.toLocaleString('en-US')} ${scene.verified === 1 ? 'claim' : 'claims'} verified` },
72	      { kind: 'cross', count: scene.flagged, text: `${scene.flagged.toLocaleString('en-US')} flagged` },
73	      { kind: 'question', count: scene.unverified ?? 0, text: `${(scene.unverified ?? 0).toLocaleString('en-US')} unverified` },
74	    ];
75	    return (
76	      <>
77	        <Rise progress={m.enter(0)} style={{ position: 'absolute', left: layout.margin, top: layout.margin + (hero - fit.height) / 2, width }}>
78	          <RepoName fit={fit} />
79	        </Rise>
80	        <Rise progress={m.span(0.5, 1)} style={{ position: 'absolute', left: layout.margin, top: below + (layout.margin + space.xl), display: 'flex', gap: space.xxl }}>
81	          {tallies.map((tally) => (
82	            <div key={tally.kind} style={{ display: 'flex', alignItems: 'center', gap: space.md, opacity: tally.count > 0 ? dim.full : dim.zero }}>
83	              <div style={{ position: 'relative', width: TALLY_MARK, height: TALLY_MARK }}>
84	                <Mark kind={tally.kind} x={TALLY_MARK / 2} y={TALLY_MARK / 2} width={TALLY_MARK * SHAPE[tally.kind].width * 1.5} height={TALLY_MARK * SHAPE[tally.kind].height} seed={31} weight={TALLY_STROKE} />
85	              </div>
86	              <Type face={FACE.text} size={size.text.tally} leading={leading.solid}>{tally.text}</Type>
87	            </div>
88	          ))}
89	        </Rise>
90	      </>
91	    );
92	  },
93	};
94

