// Shared by the composition and by the Node side of the renderer, so it imports nothing that needs a browser.
import type { LineTiming, Storyboard } from '@dailies/core';

export const COMPOSITION_ID = 'Reel';
export const WIDTH = 1920;
export const HEIGHT = 1080;
export const NARRATION_FILE = 'narration.wav';

/**
 * `audio` says whether `NARRATION_FILE` is in the public folder. Without it the reel is a captions cut.
 * `settled` is for review stills: every pencil mark and every step counts as already told, so the middle frame
 * of a scene shows all the scene will hold.
 */
export type ReelProps = { storyboard: Storyboard; timings: LineTiming[]; audio: boolean; settled?: boolean };
import React from 'react';
import { Composition, type CalculateMetadataFunction } from 'remotion';
import { FPS, buildTimeline } from '../timeline';
import { COMPOSITION_ID, HEIGHT, WIDTH, type ReelProps } from './config';
import { Reel } from './Reel';

// What the Studio shows before real props arrive; a render always passes its own.
const preview: ReelProps = {
  storyboard: {
    runId: 'preview',
    repo: 'owner/repository',
    targetSec: 75,
    facts: {},
    scenes: [
      { id: 'title', type: 'title', lines: [], repo: 'owner/repository', windowLabel: 'Last 7 days', sessionCount: 0, commitCount: 0 },
      { id: 'end', type: 'end', lines: [], repo: 'owner/repository', verified: 0, flagged: 0, unverified: 0 },
    ],
  },
  timings: [],
  audio: false,
};

const calculateMetadata: CalculateMetadataFunction<ReelProps> = ({ props }) => ({
  durationInFrames: buildTimeline(props.storyboard, props.timings, FPS).totalFrames,
});

export const Root: React.FC = () => (
  <Composition id={COMPOSITION_ID} component={Reel} width={WIDTH} height={HEIGHT} fps={FPS} defaultProps={preview} calculateMetadata={calculateMetadata} />
);
import { registerRoot } from 'remotion';
import { Root } from './Root';

registerRoot(Root);
// Film geometry: pure. A strip is laid out in "rest px": the scene as it sits when the lens has landed, with the
// origin at the point under the centre of the lens and x running along the film. Film.tsx draws from these boxes.
import { theme } from '../theme';

const { film } = theme;

export interface Strip {
  /** Screen px of one perforation pitch. */
  perf: number;
  /** Perforations per frame: eight for a full landscape frame, four for a portrait half-frame. */
  per: number;
  /** Screen px from one frame to the next. */
  pitch: number;
  height: number;
  frame: { top: number; width: number; height: number; radius: number };
}

/** The strip under a lens whose full-frame pitch is `unit` px. */
export function stripOf(unit: number, half: boolean): Strip {
  const per = half ? film.perforations / 2 : film.perforations;
  const perf = unit / film.perforations;
  const pitch = perf * per;
  return {
    perf,
    per,
    pitch,
    height: unit * film.height,
    frame: {
      top: unit * (film.frame.top - film.height / 2),
      width: pitch - unit * film.frame.gap,
      height: unit * film.frame.height,
      radius: Math.max(film.frame.minRadius, unit * film.frame.radius),
    },
  };
}

export interface Box { left: number; top: number; width: number; height: number }

/** The picture area of frame `k`, when the lens rests `at` perforations past the start of frame 0. */
export function frameBox(strip: Strip, at: number, k: number): Box {
  return { left: (k * strip.per - at) * strip.perf + (strip.pitch - strip.frame.width) / 2, top: strip.frame.top, width: strip.frame.width, height: strip.frame.height };
}

/** The frames whose picture area reaches into `from..to` px along the strip. */
export function framesWithin(strip: Strip, at: number, from: number, to: number): number[] {
  const first = Math.floor(from / strip.pitch + at / strip.per) - 1;
  const last = Math.ceil(to / strip.pitch + at / strip.per) + 1;
  const frames: number[] = [];
  for (let k = first; k <= last; k++) {
    const box = frameBox(strip, at, k);
    if (box.left + box.width > from && box.left < to) frames.push(k);
  }
  return frames;
}
// When things happen inside a scene: pure. Narration lines become frame spans, and marks and strip advances are
// cued from the line that tells them.
import { Easing, interpolate } from 'remotion';
import type { LineTiming, Scene } from '@dailies/core';
import { theme } from '../theme';

const { motion } = theme;

/** The most steps a terminal scene shows; the schema allows no more. */
export const MAX_STEPS = 4;

/** A stretch of a scene, in frames counted from the scene's cut. */
export interface Span { start: number; end: number }

/** The span of each narration line of `scene`. A line without a timing takes the whole scene. */
export function lineSpans(scene: Scene, timings: LineTiming[], slot: { startFrame: number; durationInFrames: number }, audioStartFrame: number, fps: number): Span[] {
  const byLine = new Map(timings.map((t) => [t.lineId, t]));
  const clamp = (f: number) => Math.max(0, Math.min(slot.durationInFrames, f));
  return scene.lines.map((line) => {
    const t = byLine.get(line.id);
    if (!t) return { start: 0, end: slot.durationInFrames };
    const start = clamp(audioStartFrame + Math.round(t.startSec * fps) - slot.startFrame);
    return { start, end: Math.max(start, clamp(audioStartFrame + Math.round(t.endSec * fps) - slot.startFrame)) };
  });
}

/**
 * The line that tells each of a scene's items: the first line citing the item's entry, otherwise the line at
 * the same place in the scene. The result never runs backwards, so items are told in the order they are shown.
 */
export function linesOfItems(entryIds: string[], lines: Scene['lines']): number[] {
  let last = 0;
  return entryIds.map((entryId, i) => {
    const cited = lines.findIndex((line) => line.evidence.some((e) => e.type === 'entry' && e.entryId === entryId));
    const line = cited >= 0 ? cited : Math.min(lines.length - 1, Math.floor((i * lines.length) / entryIds.length));
    last = Math.max(last, line, 0);
    return last;
  });
}

/** The span in which each item is told. Items that share a line share its span in equal parts, in order. */
export function itemSpans(lineOf: number[], lines: Span[], whole: Span): Span[] {
  return lineOf.map((line, i) => {
    const span = lines[line] ?? whole;
    const sharing = lineOf.filter((l) => l === line).length;
    const place = lineOf.slice(0, i).filter((l) => l === line).length;
    const part = (span.end - span.start) / sharing;
    return { start: span.start + part * place, end: span.start + part * (place + 1) };
  });
}

/** The frame at which the mark of an item starts to draw: a little way into the span that tells it, never before `earliest`. */
export function cueFrame(span: Span, fps: number, earliest = 0): number {
  const into = Math.min(motion.cueMaxSec * fps, Math.max(motion.cueMinSec * fps, (span.end - span.start) * motion.cueShare));
  return Math.max(earliest, span.start + into);
}

const STEP_EASE = Easing.bezier(0.5, 0, 0.15, 1);

/**
 * Which item is under the lens at `frame`, as a fraction while the strip advances from one to the next.
 * The strip moves on when the next item starts to be told.
 */
export function stepPosition(spans: Span[], frame: number, fps: number): number {
  const stepFrames = Math.max(1, motion.stepSec * fps);
  return spans.slice(1).reduce((pos, span) => pos + interpolate(frame, [span.start, span.start + stepFrames], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: STEP_EASE }), 0);
}

/** The span in which each step of a scene is told, from the entries its lines cite. */
export function stepSpans(entryIds: string[], lines: Scene['lines'], spans: Span[], duration: number): Span[] {
  return itemSpans(linesOfItems(entryIds, lines), spans, { start: 0, end: duration });
}

/** Which step of a scene is under the lens at `frame`: always 0 for a scene whose strip does not advance. */
export function stepAt(scene: Scene, spans: Span[], frame: number, duration: number, fps: number, settled: boolean): number {
  if (scene.type !== 'terminal') return 0;
  const steps = scene.steps.slice(0, MAX_STEPS);
  if (settled) return steps.length - 1;
  return stepPosition(stepSpans(steps.map((s) => s.entryId), scene.lines, spans, duration), frame, fps);
}
export type { Timeline } from './timeline';
export { buildTimeline } from './timeline';
export { toSrt } from './srt';
export { renderReel, renderStills } from './render';
import type { LineTiming, Storyboard } from '@dailies/core';

export interface Timeline { fps: number; totalFrames: number; audioStartFrame: number; scenes: { sceneId: string; startFrame: number; durationInFrames: number }[] }

export const FPS = 30;
const TITLE_SEC = 2.5;
const END_SEC = 3;
const TAIL_SEC = 0.4;   // the last spoken scene holds this long after its last line

export interface TimedLine { id: string; text: string; sceneId: string; startSec: number; endSec: number }

/** Every narration line in storyboard order with its timing. A line without a timing is an error, never a guess. */
export function timedLines(sb: Storyboard, timings: LineTiming[]): TimedLine[] {
  const byLine = new Map(timings.map((t) => [t.lineId, t]));
  return sb.scenes.flatMap((scene) =>
    scene.lines.map((line) => {
      const t = byLine.get(line.id);
      if (!t) throw new Error(`no timing for line ${line.id} in scene ${scene.id}`);
      return { id: line.id, text: line.text, sceneId: scene.id, startSec: t.startSec, endSec: t.endSec };
    }),
  );
}

/** The line being spoken `sec` seconds into the narration, or null in a pause and outside it. */
export function lineAt(sb: Storyboard, timings: LineTiming[], sec: number): TimedLine | null {
  return timedLines(sb, timings).find((l) => sec >= l.startSec && sec < l.endSec) ?? null;
}

export function buildTimeline(sb: Storyboard, timings: LineTiming[], fps: number = FPS): Timeline {
  const title = sb.scenes[0];
  const end = sb.scenes.at(-1);
  if (title?.type !== 'title') throw new Error('storyboard must start with a title scene');
  if (sb.scenes.length < 2 || end?.type !== 'end') throw new Error('storyboard must finish with an end scene');
  const spoken = sb.scenes.slice(1, -1);
  spoken.forEach((scene, i) => {
    if (scene.type === 'title' || scene.type === 'end') throw new Error(`scene ${i + 1} (${scene.type}) cannot sit between spoken scenes`);
    if (scene.lines.length === 0) throw new Error(`scene ${scene.id} has no narration lines`);
  });

  const lines = new Map(timedLines(sb, timings).map((l) => [l.id, l]));
  const frames = (sec: number) => Math.round(sec * fps);
  const audioStartFrame = frames(TITLE_SEC);

  // Cut points between spoken scenes. Each is pushed at least one frame past the previous one,
  // so timings that collide or run backwards still give every scene a positive length.
  const cuts = [audioStartFrame];
  for (const scene of spoken.slice(1)) {
    const firstLine = lines.get(scene.lines[0]!.id)!;
    cuts.push(Math.max(cuts.at(-1)! + 1, audioStartFrame + frames(firstLine.startSec)));
  }
  const lastScene = spoken.at(-1);
  if (lastScene) {
    const lastLine = lines.get(lastScene.lines.at(-1)!.id)!;
    cuts.push(Math.max(cuts.at(-1)! + 1, audioStartFrame + frames(lastLine.endSec + TAIL_SEC)));
  }

  const scenes = [
    { sceneId: title.id, startFrame: 0, durationInFrames: audioStartFrame },
    ...spoken.map((scene, i) => ({ sceneId: scene.id, startFrame: cuts[i]!, durationInFrames: cuts[i + 1]! - cuts[i]! })),
    { sceneId: end.id, startFrame: cuts.at(-1)!, durationInFrames: frames(END_SEC) },
  ];
  return { fps, totalFrames: cuts.at(-1)! + frames(END_SEC), audioStartFrame, scenes };
}

