18	/** The review stage's own check: black segments of half a second or more. */
19	const blackSegments = (path: string): string[] =>
20	  (spawnSync('ffmpeg', ['-i', path, '-vf', 'blackdetect=d=0.5', '-an', '-f', 'null', '-'], { encoding: 'utf8' }).stderr.match(/black_start:\S+/g) ?? []);
